parameters.jsCode:
// Extract key data points from Firecrawl scrapes and historical DB data
const albanyRaw = $('Firecrawl - Albany Market Data').item.json.data?.markdown || '';
const saratogaRaw = $('Firecrawl - Saratoga Market Data').item.json.data?.markdown || '';
const historical = $('Fetch Historical Snapshots').all().map(i => i.json);

// Truncate to avoid token overflow in Ollama
const albanySnippet = albanyRaw.substring(0, 2000);
const saratogaSnippet = saratogaRaw.substring(0, 1500);

// Build historical context string
let histContext = '';
if (historical.length > 0) {
  histContext = 'Recent DB snapshots:\n';
  historical.forEach(s => {
    histContext += `${s.area}: median $${s.median_price}, ${s.avg_dom} avg DOM, ${s.months_of_supply} mo supply\n`;
  });
}

const weekOf = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

return [{
  json: {
    albanyData: albanySnippet,
    saratogaData: saratogaSnippet,
    historicalContext: histContext,
    weekOf
  }
}];

