  "reel_script": {
    "script": "<45-second video script (110-120 words) for Mark to deliver to camera, with [B-ROLL] notes>"
  },
  "did_you_know": {
    "stat_post": "<60-80 word punchy stat post for any platform>"
  },
  "market_snapshot": {
    "albany_median": <integer or null>,
    "albany_dom": <integer or null>,
    "saratoga_median": <integer or null>,
    "saratoga_dom": <integer or null>,
    "trend_summary": "<1 sentence market trend>"
  }
}

parameters.jsCode:
const response = $('Ollama - Generate All Market Content').item.json.response;
const weekOf = $('Build Market Context').item.json.weekOf;

let content;
try {
  content = JSON.parse(response.replace(/```json/g,'').replace(/```/g,'').trim());
} catch(e) {
  // Structured fallback
  content = {
    instagram: { caption: response.substring(0, 500) },
    facebook: { post: response.substring(0, 800) },
    email_newsletter: { subject: 'Capital Region Market Update', intro: response.substring(0, 400) },
    reel_script: { script: 'See full content in email.' },
    did_you_know: { stat_post: 'Check this week\'s market data below.' },
    market_snapshot: {}
  };
}

const today = new Date().toISOString().split('T')[0];

// Save market snapshot data to DB
const snapshot = content.market_snapshot || {};

// Return all content pieces as separate items for batch DB insert
return [
  {
    json: {
      platform: 'instagram',
      content_type: 'market_update',
      title: `Market Update: Week of ${weekOf}`,
      content: content.instagram?.caption || '',
      scheduled_date: today,
      status: 'draft',
      generated_by: 'llama3.1:70b',
      image_notes: 'Use branded market stats graphic. Key number as overlay text.',
      _snapshot: snapshot
    }
  },
  {
    json: {
      platform: 'facebook',
      content_type: 'market_update',
      title: `Market Update: Week of ${weekOf}`,
      content: content.facebook?.post || '',
      scheduled_date: today,
      status: 'draft',
      generated_by: 'llama3.1:70b',
      image_notes: 'Use market stats infographic or neighborhood photo',
      _snapshot: snapshot
    }
  },
  {
    json: {
      platform: 'email',
      content_type: 'market_update',
      title: content.email_newsletter?.subject || `Market Update ${weekOf}`,
      content: content.email_newsletter?.intro || '',
      scheduled_date: today,
      status: 'draft',
      generated_by: 'llama3.1:70b',
      image_notes: 'Add data table below intro. Use consistent branded header.',
      _snapshot: snapshot
    }
  },
  {
    json: {
      platform: 'tiktok',
      content_type: 'market_update',
      title: `Market Update Reel: ${weekOf}`,
      content: content.reel_script?.script || '',
      scheduled_date: today,
      status: 'draft',
      generated_by: 'llama3.1:70b',
      image_notes: 'Film at desk or driving around neighborhood. Show data on screen.',
      _snapshot: snapshot
    }
  },
  {
    json: {
      platform: 'all',
      content_type: 'market_update',
      title: `Did You Know: ${weekOf}`,
      content: content.did_you_know?.stat_post || '',
      scheduled_date: today,
      status: 'draft',
      generated_by: 'llama3.1:70b',
      image_notes: 'Bold stat graphic with brand colors. Square format.',
      _snapshot: snapshot
    }
  }
];

